import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const Cart = () => {
  const userId = sessionStorage.getItem("userId");
  const [cartItems, setCartItems] = useState([]);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/cart/user/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          setCartItems(data);
          const calculatedTotal = data.reduce((sum, item) => sum + parseFloat(item.price), 0);
          setTotal(calculatedTotal);
        })
        .catch((err) => console.error("Failed to load cart items:", err));
    }
  }, [userId]);

  const handleRemove = async (id) => {
    await fetch(`${API_BASE_URL}/api/cart/${id}`, { method: "DELETE" });
    setCartItems((prev) => prev.filter((item) => item.id !== id));
    setTotal((prev) => prev - cartItems.find((item) => item.id === id).price);
  };

  const handleCheckout = () => {
    alert("Proceed to checkout logic not implemented yet!");
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="cart-container" style={{ padding: "40px 20px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>Your Cart</h2>
        {cartItems.length === 0 ? (
          <p style={{ textAlign: "center" }}>Your cart is empty.</p>
        ) : (
          <div className="item-grid">
            {cartItems.map((item) => (
              <div className="item-card" key={item.id}>
                <img src={item.image} alt={item.title} className="sales-item-img" />
                <h4>{item.title}</h4>
                <p>{item.description}</p>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                <button className="remove-btn" onClick={() => handleRemove(item.id)}>Remove</button>
              </div>
            ))}
          </div>
        )}

        {cartItems.length > 0 && (
          <div className="cart-summary" style={{ textAlign: "center", marginTop: "32px" }}>
            <h3>Total: ${total.toFixed(2)}</h3>
            <button className="checkout-btn" onClick={handleCheckout}>
              Proceed to Checkout
            </button>
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default Cart;
